// Check for the resultJson in item.json.data
if (
  item &&
  item.json &&
  item.json.data &&
  item.json.data.resultJson
) {
  // Parse resultJson if it's a string
  const resultJson = typeof item.json.data.resultJson === 'string'
    ? JSON.parse(item.json.data.resultJson)
    : item.json.data.resultJson;

  // Extract the first URL
  if (
    resultJson.resultUrls &&
    resultJson.resultUrls.length > 0
  ) {
    url = resultJson.resultUrls[0];
  }
}

// Return the URL as a new property
return {
  json: { url },
};

let url = null;

// Access the deeply nested resultJson as a string
if (
  item.json &&
  item.json.data &&
  item.json.data.resultJson
) {
  // Parse resultJson string to object
  const resultObj = JSON.parse(item.json.data.resultJson);

  // Extract the first URL if available
  if (
    resultObj.resultUrls &&
    resultObj.resultUrls.length > 0
  ) {
    url = resultObj.resultUrls[0];
  }
}

// Output URL as sole value in the returned object for this item
return {
  json: { url }
};

function buildScenes(input) {
  const duration = 5000; // ms per keyframe

  // Build video track
  const videoKeyframes = input.video_url.map((url, index) => ({
    url,
    timestamp: index * duration,
    duration
  }));

  const video = {
    id: "1",
    type: "video",
    keyframes: videoKeyframes
  };

  // Build audio tracks (array of objects, not one object)
  const audio = input.voice_url.map((url, index) => ({
    id: String(index + 2),
    type: "audio",
    keyframes: [
      {
        url,
        timestamp: index * duration,
        duration
      }
    ]
  }));

  return {
    ffmpeg: {
      video,
      audio // this will now be an array of objects
    }
  };
}

// Get input from n8n
const input = $input.first().json;

// Wrap the result in an array with a `json` property
return [
  {
    json: buildScenes(input)
  }
];

